export function attachLoadingOnSubmit(t,e={}){const n=document.getElementById(t);if(!n)return;const{buttonId:d,spinnerId:o,textId:c,loadingText:m="Procesando..."}=e;n.addEventListener("submit",()=>{const t=document.getElementById(d),e=document.getElementById(o),n=document.getElementById(c);t&&e&&n&&(t.disabled=!0,e.classList.remove("d-none"),n.textContent=m)})}